class Contract {
public:
  static std::expected<Contract, Error> create(Customer c, Supplier s) {
    if (!c.valid() || !s.valid())
      return std::unexpected(Error::InvalidParty);   // rejected BEFORE construction
    return Contract(std::move(c), std::move(s));     // born valid (C++17 elision)
  }
private:
  friend class ContractEssence;                      // restricted creation path
  Contract(Customer c, Supplier s);
};
